		return nil, 0, fmt.Errorf("iterate sbom page: %w", err)
	}
	if err := rows.Close(); err != nil {
		return nil, 0, fmt.Errorf("close sbom page: %w", err)
	}

	for i, id := range ids {
		loaded, err := loadSBOM(ctx, s.db, id)
